package de.corporate.lc.lc.api; import de.corporate.lc.lc.domain.Amendment;import de.corporate.lc.lc.service.AmendmentService;import org.springframework.http.MediaType;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api") public class AmendmentController{private final AmendmentService service;public AmendmentController(AmendmentService s){service=s;}@PostMapping(value="/lcs/import/mt707",consumes=MediaType.TEXT_PLAIN_VALUE)public Amendment importMt707(@RequestBody String raw){return service.importMt707(raw);}@GetMapping("/lcs/{id}/amendments")public List<Amendment> amendments(@PathVariable UUID id){return service.forLc(id);}}
